import mongoose from "mongoose";
import WorkCalendar from "../src/models/workCalendarModel.js";
import WorkItem from "../src/models/workItemModel.js";
import dotenv from "dotenv";

// Load environment variables
dotenv.config({ path: './backend/.env' });

const fixWorkCalendarDates = async () => {
  try {
    console.log("🔧 Connecting to database...");
    await mongoose.connect(process.env.MONGO_URI);
    console.log("✅ Connected to database");

    console.log("\n🔍 Finding work calendar entries created from work items...");
    
    // Find all work calendar entries that were auto-generated from work items
    const workCalendarEntries = await WorkCalendar.find({
      sourceModel: 'WorkItem',
      isAutoGenerated: true
    }).populate('sourceId');

    console.log(`Found ${workCalendarEntries.length} work calendar entries to check`);

    let fixedCount = 0;
    const fixedEntries = [];

    for (const entry of workCalendarEntries) {
      if (!entry.sourceId) {
        console.log(`⚠️  Skipping entry ${entry._id} - source work item not found`);
        continue;
      }

      const workItem = entry.sourceId;
      const dueDate = new Date(workItem.dueDate);
      
      // Calculate correct dates (both start and end on due date)
      const correctStartDate = new Date(dueDate);
      correctStartDate.setHours(9, 0, 0, 0); // 9 AM on due date
      
      const correctEndDate = new Date(dueDate);
      correctEndDate.setHours(17, 0, 0, 0); // 5 PM on due date

      // Check if dates need fixing
      const currentStartDate = new Date(entry.startDate);
      const currentEndDate = new Date(entry.endDate);

      const needsStartFix = currentStartDate.getTime() !== correctStartDate.getTime();
      const needsEndFix = currentEndDate.getTime() !== correctEndDate.getTime();

      if (needsStartFix || needsEndFix) {
        console.log(`🔧 Fixing entry: ${entry.title}`);
        console.log(`   Work Item Due Date: ${dueDate.toDateString()}`);
        console.log(`   Old Start: ${currentStartDate.toLocaleString()}`);
        console.log(`   Old End: ${currentEndDate.toLocaleString()}`);
        console.log(`   New Start: ${correctStartDate.toLocaleString()}`);
        console.log(`   New End: ${correctEndDate.toLocaleString()}`);

        // Update the entry
        entry.startDate = correctStartDate;
        entry.endDate = correctEndDate;
        await entry.save();

        fixedCount++;
        fixedEntries.push({
          id: entry._id,
          title: entry.title,
          workItemDueDate: dueDate.toDateString(),
          oldStart: currentStartDate.toLocaleString(),
          oldEnd: currentEndDate.toLocaleString(),
          newStart: correctStartDate.toLocaleString(),
          newEnd: correctEndDate.toLocaleString()
        });
      }
    }

    console.log(`\n✅ Fix completed!`);
    console.log(`📊 Summary:`);
    console.log(`   Total entries checked: ${workCalendarEntries.length}`);
    console.log(`   Entries fixed: ${fixedCount}`);
    console.log(`   Entries already correct: ${workCalendarEntries.length - fixedCount}`);

    if (fixedEntries.length > 0) {
      console.log(`\n📋 Fixed entries:`);
      fixedEntries.forEach((entry, index) => {
        console.log(`${index + 1}. ${entry.title}`);
        console.log(`   Due: ${entry.workItemDueDate}`);
        console.log(`   Fixed: ${entry.oldStart} → ${entry.newStart}`);
      });
    }

  } catch (error) {
    console.error("❌ Error during fix:", error);
  } finally {
    await mongoose.disconnect();
    console.log("🔌 Disconnected from database");
  }
};

// Run the fix
fixWorkCalendarDates();